Tool response:
Tool: update_exam_registration
Description: Update an exam registration with new session and results.
Parameters:
    {
      "type": "object",
      "properties": {
        "registration_id": {
          "type": "integer",
          "title": "Registration Id",
          "description": ""
        },
        "new_session_id": {
          "type": "integer",
          "title": "New Session Id"
        },
        "outcome": {
          "type": "string",
          "pattern": "^(pass|fail)$",
          "title": "Outcome"
        },
        "score": {
          "type": "number",
          "maximum": 100.0,
          "minimum": 0.0,
          "title": "Score"
        }
      },
      "required": [
        "registration_id",
        "new_session_id",
        "outcome",
        "score"
      ]
    }

Tool response:
Tool: find_available_exam_sessions
Description: Find available exam sessions for a specific exam.
Parameters:
    {
      "type": "object",
      "properties": {
        "exam_id": {
          "type": "integer",
          "description": "The ID of the exam to find sessions for",
          "title": "Exam Id"
        },
        "session_type": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Filter sessions by type ('online_proctored', 'in_person', 'hybrid')",
          "title": "Session Type"
        },
        "start_date": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Filter sessions starting on or after this date (YYYY-MM-DD)",
          "title": "Start Date"
        },
        "end_date": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Filter sessions ending on or before this date (YYYY-MM-DD)",
          "title": "End Date"
        }
      },
      "required": [
        "exam_id"
      ]
    }

Tool response:
Tool: get_exam_registration_details
Description: Get detailed information about an exam registration.
Parameters:
    {
      "type": "object",
      "properties": {
        "registration_id": {
          "type": "integer",
          "title": "Registration Id",
          "description": ""
        }
      },
      "required": [
        "registration_id"
      ]
    }
